pub fn solve(input: Vec<char>) -> Vec<char> {
    // Only the first two characters matter, and per spec they are digits.
    let a = input[0];
    let b = input[1];

    fn good_count_digit(c: char) -> u32 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => unreachable!("spec requires an ASCII digit"),
        }
    }

    let p: u32 = good_count_digit(a) * good_count_digit(b); // in 1..=49 by spec

    // Convert `p` to canonical decimal (no leading zeros).
    let mut out: Vec<char> = if p < 10 {
        vec![char::from_u32(('0' as u32) + p).unwrap()]
    } else {
        let tens = p / 10;
        let ones = p % 10;
        vec![
            char::from_u32(('0' as u32) + tens).unwrap(),
            char::from_u32(('0' as u32) + ones).unwrap(),
        ]
    };

    out.push('\n');
    out
}